/* Climate City data integration for the adapted Curevo template. */
(()=>{'use strict';
const toggle=document.getElementById('mobileToggle'),menu=document.getElementById('mobileMenu');
function closeMenu(){menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation')}
toggle.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){closeMenu();toggle.focus()}});document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!toggle.contains(e.target))closeMenu()});
const categories={museum:'Culture & heritage',hospital:'Healthcare & wellbeing',schools:'Education & learning',sports:'Sport & active living',market:'Enterprise & local life',diplomatic:'International exchange',wildlife:'Nature & conservation',hotel:'Hospitality',landscape:'Landscape & gardens',waterfront:'Waterfront leisure',station:'Proposed mobility',homes:'Homes & neighbourhoods',energy:'Clean energy',food:'Food & agriculture'};
fetch('data.json').then(r=>{if(!r.ok)throw Error('Destination data unavailable');return r.json()}).then(data=>{const ds=data.destinations||[];const byId=Object.fromEntries(ds.map(d=>[d.id,d]));document.querySelectorAll('[data-image]').forEach(img=>{const[id,n]=img.dataset.image.split(':');const d=byId[id],v=d?.images?.[Number(n)]||d?.images?.[0];if(v){img.src=typeof v==='string'?v:v.src;img.alt=typeof v==='string'?d.title:v.title||d.title}});const cards=document.getElementById('destinationCards');for(const id of ['hotel','schools','market','diplomatic','sports','wildlife']){const d=byId[id];if(!d)continue;const a=document.createElement('a');a.className='destination-card';a.href='explore.html#'+id;const visual=document.createElement('div');visual.className='destination-card-image';const img=document.createElement('img');img.src=d.images?.[0]?.src||data.masterplan||'assets/masterplan.jpg';img.alt=d.images?.[0]?.title||d.title;img.loading='lazy';const arrow=document.createElement('span');arrow.className='card-arrow';arrow.textContent='';visual.append(img,arrow);const meta=document.createElement('div');meta.className='destination-card-meta';const copy=document.createElement('div');const h=document.createElement('h3');h.textContent=d.title;const p=document.createElement('p');p.textContent=categories[id]||d.eyebrow||'';copy.append(h,p);const count=document.createElement('span');count.textContent=(d.images?.length||1)+' VIEWS';meta.append(copy,count);a.append(visual,meta);cards.append(a)}const places=document.getElementById('allPlaces');ds.forEach((d,i)=>{const a=document.createElement('a');a.className='place-link';a.href='explore.html#'+d.id;const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');const name=document.createElement('span');name.textContent=d.title;const arrow=document.createElement('b');arrow.textContent='';a.append(num,name,arrow);places.append(a)})}).catch(()=>{const p=document.createElement('p');p.textContent='Explore all destinations in the interactive masterplan.';const a=document.createElement('a');a.href='explore.html';a.className='pill-button';a.textContent='Open the masterplan ';document.getElementById('allPlaces').append(p,a)});
})();

(()=>{const film=document.getElementById('cityFilm'),play=document.getElementById('playCityFilm'),panel=document.getElementById('virtualTourPanel'),error=document.getElementById('filmError');
if(!film||!play)return;
play.addEventListener('click',async()=>{error.hidden=true;film.controls=true;try{await film.play();}catch(e){error.hidden=false;film.controls=false;play.hidden=false;}});
film.addEventListener('playing',()=>{play.hidden=true;panel.classList.add('is-playing');film.focus();});
film.addEventListener('ended',()=>{play.hidden=false;film.controls=false;panel.classList.remove('is-playing');});
film.addEventListener('error',()=>{error.hidden=false;play.hidden=false;});
})();
